def create_icon(name: str, color: str = None, size: int = 24) -> QIcon:
    """Cria um QIcon a partir do nome e cor.

    Args:
        name: Nome do ícone (chave do dicionário ICONS)
        color: Cor em hex (ex: "#1A1A1B") ou None para preto
        size: Tamanho em pixels

    Returns:
        QIcon com o ícone renderizado
    """
    if name not in ICONS:
        return QIcon()

    color = color or "#000000"
    path_data = ICONS[name]

    svg = f"""<?xml version="1.0" encoding="UTF-8"?>
<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none"
     stroke="{color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
{path_data}
</svg>"""

    renderer = QSvgRenderer(svg.encode("utf-8"))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)

    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter)
    painter.end()

    return QIcon(pixmap)


def icon(name: str, color: str = None, size: int = 24) -> QIcon:
    """Atalho para create_icon."""
    return create_icon(name, color, size)


def list_icons() -> list[str]:
    """Retorna lista de todos os nomes de ícones disponíveis."""
    return sorted(ICONS.keys())